Here's a Python program that meets your requirements. This program uses a dictionary to store student records, where the outer dictionary's keys are student names, and the inner dictionaries have 'age' and 'grade' as values. The program allows users to add, remove, and search for student records.

```python
student_records = {}

def add_student(name, age, grade):
    """Add a student record to the dictionary."""
    if name not in student_records:
        student_records[name] = {'age': age, 'grade': grade}
        print(f"{name} added.")
    else:
        print(f"Student {name} already exists.")

def remove_student(name):
    """Remove a student record from the dictionary."""
    if name in student_records:
        del student_records[name]
        print(f"Student {name} removed.")
    else:
        print(f"Student {name} not found.")

def search_student(name):
    """Search for a student record in the dictionary."""
    if name in student_records:
        print(f"{name}: {student_records[name]['age']} years old, Grade {student_records[name]['grade']}.")
    else:
        print(f"Student {name} not found.")

# Main program
while True:
    user_input = input("Enter a command (Add, Remove, Search, Exit): ").lower()

    if user_input == "add":
        name = input("Enter student name: ")
        age = int(input("Enter student age: "))
        grade = input("Enter student grade: ")
        add_student(name, age, grade)

    elif user_input == "remove":
        name = input("Enter student name to remove: ")
        remove_student(name)

    elif user_input == "search":
        name = input("Enter student name to search: ")
        search_student(name)

    elif user_input == "exit":
        print("Exiting the program...")
        break

    else:
        print("Invalid command. Please try again.")
```

This program will keep prompting the user for commands until they enter 'exit'. Each command will be handled by the corresponding function, and the program will print the results accordingly.
